          "bn": "আজ থেকে একটা অভ্যাস করো: সালাতে {{إِيَّاكَ نَعْبُدُ}} পড়ার সময় মনে মনে বলো ‘কেবল তোমারই ইবাদত করি’। প্রতিদিন একটি করে শব্দের অর্থ মনে আনলে এক সপ্তাহেই পুরো ফাতিহা অর্থসহ মনে থাকবে।",
          "en": "Start a habit today: when you recite {{إِيَّاكَ نَعْبُدُ}} in salah, think ‘You alone we worship’. Recall one word's meaning each day, and within a week you'll pray all of Al-Fatiha with its meaning."
