          "bn": "এখন ফাতিহার {{مَغْضُوب}} শব্দটি আবার দেখো: মূল غ ض ب (রাগ), ছাঁচ {{مَفْعُول}} — তাই অর্থ ‘যার উপর রাগ করা হয়েছে’। আর বাংলার **মাখলুক** (সৃষ্টি) = {{مَخْلُوق}}, **খালিক** (স্রষ্টা) = {{خَالِق}}, **জালিম-মজলুম** = {{ظَالِم}}-{{مَظْلُوم}}, **মাবুদ** = {{مَعْبُود}}। দেখলে তো, ছাঁচ জানলে শব্দ নিজেই অর্থ বলে দেয়!",
          "en": "Now look again at {{مَغْضُوب}} from Al-Fatiha: root غ ض ب (anger), pattern {{مَفْعُول}} — so it means ‘one who has been angered against’. And Bangla **makhluk** (creation) = {{مَخْلُوق}}, **khalik** (Creator) = {{خَالِق}}, **jalim–majlum** (oppressor–oppressed) = {{ظَالِم}}–{{مَظْلُوم}}, **mabud** = {{مَعْبُود}}. See? Know the pattern and the word tells you its meaning!"
